import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 33.33, D: 0.1, E: 100, F: 100.5 }
let server, base

before(async () => {
  const pricing = { priceOf: async (sku) => prices[sku] }
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

async function totalFor(items) {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  assert.equal(res.status, 201)
  const order = await res.json()
  const fetched = await (await fetch(`${base}/orders/${order.id}`)).json()
  assert.equal(fetched.total, order.total)
  return order.total
}

test('sums unit price * qty across items', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 3 }, { sku: 'B', qty: 2 }]), 80)
})

test('order of exactly 100 gets no discount', async () => {
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 100)
})

test('order just over 100 gets 10% off (then floored)', async () => {
  // 100.5 * 0.9 = 90.45 -> 90
  assert.equal(await totalFor([{ sku: 'F', qty: 1 }]), 90)
})

test('larger order: 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'E', qty: 3 }]), 270)
  assert.equal(await totalFor([{ sku: 'B', qty: 40 }]), 900)
})

test('discount applies to whole total, not just the part above 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)
})

test('total is floored to whole euros (cents dropped, not rounded)', async () => {
  // 33.33 * 2 = 66.66 -> 66 (no discount)
  assert.equal(await totalFor([{ sku: 'C', qty: 2 }]), 66)
  // 33.33 * 4 = 133.32 * 0.9 = 119.988 -> 119 (rounding would give 120)
  assert.equal(await totalFor([{ sku: 'C', qty: 4 }]), 119)
})

test('floating point: 0.1 * 3 style sums stay stable', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 1000 }]), 90) // 100.00000000000001-ish * 0.9
})

test('rejects empty items', async () => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [] }) })
  assert.equal(res.status, 400)
})
EOF
